package br.com.loja.order;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;@Entity @Table(name="customer_orders")public class CustomerOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String userEmail;private String customerName;@Column(length=500)private String shippingAddress;@Enumerated(EnumType.STRING)private OrderStatus status;private LocalDateTime createdAt;@Column(precision=12,scale=2)private BigDecimal total=BigDecimal.ZERO;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)private List<OrderItem> items=new ArrayList<>();public CustomerOrder(){}public CustomerOrder(String e,String n,String a){userEmail=e;customerName=n;shippingAddress=a;status=OrderStatus.PENDING;createdAt=LocalDateTime.now();}public void add(OrderItem i){i.setOrder(this);items.add(i);total=total.add(i.getSubtotal());}public Long getId(){return id;}public String getUserEmail(){return userEmail;}public String getCustomerName(){return customerName;}public String getShippingAddress(){return shippingAddress;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus s){status=s;}public LocalDateTime getCreatedAt(){return createdAt;}public BigDecimal getTotal(){return total;}public List<OrderItem> getItems(){return items;}}